const projects=`<section class="page-intro wrap"><div class="eyebrow">01 / PROGETTI</div><h1>Il digitale, al servizio<br>della tua <span class="accent">attività.</span></h1><p>Soluzioni nate da esigenze concrete.<br>Il nostro primo passo è dedicato a chi lavora nell’ospitalità.</p></section><section class="wrap project-list"><div class="projects-grid">${projectCards}</div></section>`;
const toodo=`<section class="wrap toodo-intro"><a class="plain-link" href="/progetti/">← Tutti i progetti</a><div class="toodo-hero"><div><div class="eyebrow">TOODO / PROGRESSIVE WEB APP</div><h1>Più tempo per<br>chi <span class="accent">accogli.</span></h1><p>Il gestionale di Horudev pensato per ristoranti, bar, hotel e pasticcerie. Nasce per semplificare l’organizzazione quotidiana e lasciare più spazio a ciò che conta: i tuoi clienti.</p><div class="actions"><a class="button" href="#richiedi-accesso">Richiedi accesso alla Closed Alpha ↗</a></div><p class="form-note">Accesso su richiesta · Prodotto in fase di test</p></div><div class="toodo-panel"><span class="badge">Closed Alpha</span><strong class="toodo-wordmark">toodo<span>.</span></strong><p>Meno complessità.<br>Più ospitalità.</p><div class="sector-list"><span>Ristoranti</span><span>Bar</span><span>Hotel</span><span>Pasticcerie</span></div></div></div></section><section class="wrap toodo-overview"><div class="section-head"><div><div class="eyebrow">IL PROGETTO</div><h2>Costruiamolo intorno al lavoro reale.</h2></div></div><div class="toodo-pillars"><article><span>01 / IL TUO SETTORE</span><h3>Ospitalità al centro.</h3><p>Un gestionale dedicato alle esigenze di chi accoglie e serve clienti ogni giorno, dal piccolo bar alla struttura alberghiera.</p></article><article><span>02 / LA TECNOLOGIA</span><h3>Un’applicazione web.</h3><p>Toodo è una Progressive Web App: il progetto porta l’esperienza di un’app nel web, con un’interfaccia pensata per essere semplice da usare.</p></article><article><span>03 / IL TUO CONTRIBUTO</span><h3>La tua esperienza conta.</h3><p>La Closed Alpha è l’occasione per provare una versione iniziale, condividere le necessità della tua attività e contribuire con il tuo feedback.</p></article></div></section><section class="wrap alpha-section" id="richiedi-accesso"><div class="alpha-copy"><div class="eyebrow">PARTECIPA ALLA CLOSED ALPHA</div><h2>Porta la tua attività<br>nel prossimo <span class="accent">passo.</span></h2><p>Raccontaci chi sei e cosa vorresti semplificare. Valuteremo la richiesta e ti contatteremo via email per gli eventuali passi successivi.</p><div class="alpha-note"><h3>Cosa significa Closed Alpha?</h3><p>Una versione iniziale riservata a un gruppo di test. Funzionalità e disponibilità possono cambiare: la richiesta non garantisce l’accesso e non attiva alcun acquisto.</p></div><a class="plain-link" href="mailto:horudev@gmail.com">Preferisci scriverci? horudev@gmail.com ↗</a></div><form id="alpha-form" class="contact-form"><h3>Richiedi l’accesso</h3><p class="alpha-form-intro">Tutti i campi sono obbligatori.</p><div class="form-row"><div><label for="alpha-name">Nome e cognome</label><input id="alpha-name" name="name" autocomplete="name" required maxlength="100" placeholder="Il tuo nome"></div><div><label for="alpha-email">Email di lavoro</label><input id="alpha-email" name="email" type="email" autocomplete="email" required maxlength="254" placeholder="nome@azienda.it"></div></div><label for="alpha-company">Nome dell’attività</label><input id="alpha-company" name="company" autocomplete="organization" required maxlength="150" placeholder="Come si chiama la tua attività?"><label for="alpha-sector">Tipo di attività</label><select id="alpha-sector" name="sector" required><option value="" disabled selected>Seleziona il tuo settore</option>Ristorante</option><option>Bar</option><option>Hotel</option><option>Pasticceria</option><option>Altro</option></select><label for="alpha-needs">Cosa vorresti semplificare?</label><textarea id="alpha-needs" name="needs" rows="4" required minlength="10" maxlength="2000" placeholder="Raccontaci come lavori e cosa cerchi in un gestionale…"></textarea><label class="check"><input name="privacy" type="checkbox" required><span>Ho letto l’<a href="/termini/#privacy">informativa privacy</a> e desidero essere contattato per questa richiesta.</span></label><button class="button" type="submit">Prepara la richiesta ↗</button><p class="form-note">Prepareremo un’email a horudev@gmail.com. Potrai controllarla e inviarla dal tuo programma di posta.</p><div class="alpha-result" id="alpha-result" hidden><p role="status" id="alpha-status"></p><a class="button" id="alpha-email-link">Apri l’email da inviare ↗</a></div></form></section>`;
const store=`<section class="page-intro wrap"><div class="eyebrow">02 / STORE</div><h1>Piccoli asset. <br>Nuove <span class="accent">possibilità.</span></h1><p>Risorse per chi ama creare. <br>Una parte del nostro laboratorio, a disposizione del tuo.</p></section><section class="wrap store-section"><div class="store-art" aria-hidden="true"><span class="eyebrow">HORUDEV / DEVELOPER ASSETS</span><div class="asset-symbol" aria-hidden="true">&lt;/&gt;</div><div class="asset-bottom"><span>MADE FOR BUILDERS</span><span>↗</span></div></div><div class="store-copy"><span class="badge">SU GUMROAD</span><h2>Una risorsa in più<br>per la tua prossima idea.</h2><p>Nel piccolo store Gumroad di Horudev trovi asset per sviluppatori: risorse da acquistare e contenuti da scaricare gratuitamente.</p><p>Scopri i materiali disponibili e scegli quelli adatti al tuo progetto. Le condizioni di utilizzo sono indicate nella pagina di ciascun asset.</p><a class="button" id="store-link" href="mailto:horudev@gmail.com?subject=Informazioni%20sullo%20store%20Gumroad">Richiedi il link allo store ↗</a><p class="form-note">Scrivici per ricevere il collegamento al catalogo Gumroad.</p></div></section>`;
const contacts=`<section class="page-intro wrap"><div class="eyebrow">03 / CONTATTI</div><h1>Le cose belle iniziano<br>con un <span class="accent">ciao.</span></h1><p>Un’idea da sviluppare, una domanda o una curiosità?<br>Ci fa piacere sentirti.</p></section><section class="wrap contact-grid"><div class="contact-copy"><span class="eyebrow">SCRIVICI DIRETTAMENTE</span><a class="email-link" href="mailto:horudev@gmail.com">horudev@gmail.com ↗</a><p>Raccontaci cosa hai in mente. <br>Partiamo da lì.</p><div class="newsletter"><h3>Ci sono idee in arrivo.</h3><p>Richiedi via email di ricevere novità su progetti, sviluppi e nuove risorse.</p><form id="newsletter-form"><label for="newsletter-email">La tua email</label><div class="newsletter-input"><input id="newsletter-email" name="email" type="email" autocomplete="email" placeholder="nome@esempio.it" required maxlength="254"><button aria-label="Prepara la richiesta newsletter" type="submit">↗</button></div><label class="check"><input type="checkbox" required><span>Ho letto la <a href="/termini/#privacy">privacy</a> e richiedo aggiornamenti via email.</span></label><p class="form-note">Si aprirà il tuo programma email: invia la richiesta per contattarci.</p><p class="form-status" role="status"></p></form></div></div><form id="contact-form" class="contact-form"><div class="form-row"><div><label for="name">Il tuo nome</label><input id="name" name="name" autocomplete="name" required placeholder="Come ti chiami?" maxlength="100"></div><div><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" required placeholder="nome@esempio.it" maxlength="254"></div></div><label for="subject">Di cosa parliamo?</label><input id="subject" name="subject" placeholder="Un nuovo progetto, Toodo…" required maxlength="150"><label for="message">Il tuo messaggio</label><textarea id="message" name="message" rows="5" placeholder="Raccontaci la tua idea…" required minlength="10" maxlength="4000"></textarea><label class="check"><input type="checkbox" required><span>Ho letto l’<a href="/termini/#privacy">informativa privacy</a>.</span></label><button class="button" type="submit">Prepara il messaggio <span>↗</span></button><p class="form-note">Il modulo apre un’email compilata. L’invio avviene dal tuo programma di posta.</p><p class="form-status" role="status"></p></form></section>`;
const legal=`<section class="page-intro wrap"><div class="eyebrow">INFORMAZIONI SUL SITO</div><h1>Termini <span class="accent">e privacy.</span></h1><p>Informazioni sull’utilizzo di questa versione del sito.</p></section><section class="wrap legal"><h2>Utilizzo del sito</h2><p>Questo sito presenta Horudev e i suoi progetti. Toodo è in Closed Alpha: la presenza sul sito non implica disponibilità pubblica, date di rilascio o accesso garantito. Per informazioni puoi scrivere a <a href="mailto:horudev@gmail.com">horudev@gmail.com</a>.</p><h2>Asset e store</h2><p>Gli asset sono distribuiti tramite Gumroad. Prezzi, licenze e condizioni di acquisto o download sono quelli indicati sulle singole pagine del prodotto e sulla piattaforma al momento dell’acquisto.</p><h2 id="privacy">Dati e contatti</h2><p>I moduli di questa versione non trasmettono né archiviano i dati su un server Horudev. Preparano un messaggio nel programma di posta del visitatore, che può modificarlo e scegliere se inviarlo a horudev@gmail.com. L’indirizzo e il contenuto saranno ricevuti da Horudev solo dopo l’invio tramite il servizio email scelto.</p><p>La richiesta newsletter è una richiesta via email, non un’iscrizione automatica. Per informazioni sui tuoi messaggi o per chiedere di non ricevere ulteriori aggiornamenti, scrivi allo stesso indirizzo.</p><h2 id="cookie">Cookie e preferenze</h2><p>Il sito non integra strumenti pubblicitari o di analisi. Utilizza la memoria locale del browser per ricordare il tema selezionato e la scelta nel banner. “Solo necessari” e “Accetta” chiudono il banner senza attivare tracciamenti aggiuntivi. Puoi riaprire il banner dal collegamento Cookie nel footer o cancellare queste preferenze dai dati del browser.</p><h2>Informazioni da completare</h2><p>Prima del lancio pubblico, questa pagina deve essere completata con i dati del titolare, le informazioni sul servizio di hosting e le condizioni degli eventuali servizi di contatto e newsletter che saranno attivati.</p></section>`;
const page=location.pathname.split('/').filter(Boolean)[0]||'home';
const pages={home,progetti:projects,toodo,store,contatti:contacts,termini:legal};
main.innerHTML=pages[page]||home;
if(page==='home')document.querySelector('#home-projects').innerHTML=projectCards;
document.querySelector(`[data-page="${page==='toodo'?'progetti':page}"]`)?.setAttribute('aria-current','page');
document.title=({home:'Più ordine. Più spazio al business.',progetti:'Progetti',toodo:'Toodo — Richiedi accesso alla Closed Alpha',store:'Store',contatti:'Contatti',termini:'Termini e privacy'}[page]||'Home')+' — Horudev';
document.querySelector('#year').textContent=new Date().getFullYear();
function readPreference(key){try{return localStorage.getItem(key)}catch{return null}}
function writePreference(key,value){try{localStorage.setItem(key,value)}catch{}}
const themeButton=document.querySelector('.theme-button');
function setTheme(theme){document.documentElement.dataset.theme=theme;themeButton.textContent=theme==='dark'?'☼':'☾';themeButton.setAttribute('aria-label',theme==='dark'?'Attiva tema chiaro':'Attiva tema scuro');themeButton.setAttribute('aria-pressed',String(theme==='light'))}
setTheme(readPreference('horudev-theme')==='light'?'light':'dark');
themeButton.addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';setTheme(theme);writePreference('horudev-theme',theme)});
const cookie=document.querySelector('.cookie');cookie.hidden=!!readPreference('horudev-cookie-choice');
document.querySelectorAll('[data-consent]').forEach(button=>button.addEventListener('click',()=>{writePreference('horudev-cookie-choice',button.dataset.consent);cookie.hidden=true}));
document.querySelector('#cookie-reopen').addEventListener('click',()=>{cookie.hidden=false;cookie.querySelector('button').focus()});
const contactForm=document.querySelector('#contact-form');
if(contactForm){document.querySelector('#subject').value=new URLSearchParams(location.search).get('progetto')||'';contactForm.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(contactForm);const body=`Nome: ${data.get('name')}\nEmail: ${data.get('email')}\n\n${data.get('message')}`;location.href=`mailto:horudev@gmail.com?subject=${encodeURIComponent(data.get('subject'))}&body=${encodeURIComponent(body)}`;contactForm.querySelector('.form-status').textContent='Email preparata. Completa l’invio nel programma di posta. Se non si apre, scrivi direttamente a horudev@gmail.com.'})}
const newsletterForm=document.querySelector('#newsletter-form');
newsletterForm?.addEventListener('submit',event=>{event.preventDefault();const email=new FormData(newsletterForm).get('email');location.href=`mailto:horudev@gmail.com?subject=${encodeURIComponent('Richiesta aggiornamenti Horudev')}&body=${encodeURIComponent('Ciao Horudev, vorrei ricevere aggiornamenti sui vostri progetti e risorse a questo indirizzo: '+email+'. Ho letto le informazioni privacy. Grazie!')}`;newsletterForm.querySelector('.form-status').textContent='Richiesta preparata: inviala dal tuo programma di posta. Non sei ancora iscritto automaticamente.'});
if(location.hash)requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView());




const alphaForm=document.querySelector('#alpha-form');
alphaForm?.addEventListener('submit',event=>{
  event.preventDefault();
  const data=new FormData(alphaForm);
  const body=['Ciao Horudev, vorrei richiedere accesso alla Closed Alpha di Toodo.','',`Nome: ${data.get('name')}`,`Email di lavoro: ${data.get('email')}`,`Attività: ${data.get('company')}`,`Settore: ${data.get('sector')}`,'','Esigenze della mia attività:',data.get('needs'),'','Ho letto l’informativa privacy e desidero essere contattato per questa richiesta.'].join('\n');
  document.querySelector('#alpha-email-link').href='mailto:horudev@gmail.com?subject='+encodeURIComponent('Toodo — Richiesta accesso Closed Alpha')+'&body='+encodeURIComponent(body);
  document.querySelector('#alpha-result').hidden=false;
  document.querySelector('#alpha-status').textContent='La richiesta è pronta, ma non è ancora stata inviata. Apri l’email e completa l’invio dal tuo programma di posta.';
  document.querySelector('#alpha-email-link').focus();
});
alphaForm?.addEventListener('input',()=>{document.querySelector('#alpha-result').hidden=true;document.querySelector('#alpha-email-link').removeAttribute('href')});
